import inspect
from asyncio import iscoroutinefunction
from functools import partial

def is_coroutine_callable(call):
    unwrapped = inspect.unwrap(call)
    if isinstance(unwrapped, partial):
        unwrapped = unwrapped.func

    if inspect.isroutine(unwrapped):
        return iscoroutinefunction(unwrapped)
    if inspect.isclass(unwrapped):
        return False
    dunder_call = getattr(unwrapped, "__call__", None)
    return iscoroutinefunction(dunder_call)

async def sync_func():
    return 1

def sync_func_2():
    return 1

class AsyncCall:
    def __call__(self):
        return 1
    # To make it a coroutine function, we'd need to define it as async def
    # but __call__ can't be async def in a class? No it can.

class AsyncCall2:
    async def __call__(self):
        return 1

print(f"Sync func: {is_coroutine_callable(sync_func)}") # True
print(f"Sync func 2: {is_coroutine_callable(sync_func_2)}") # False
print(f"AsyncCall: {is_coroutine_callable(AsyncCall())}") # False
print(f"AsyncCall2: {is_coroutine_callable(AsyncCall2())}") # True (because it's not a class, it's an instance)
print(f"AsyncCall2 class: {is_coroutine_callable(AsyncCall2)}") # False (because it's a class)
